"""Read-only checks on the Orange Pi. Does not stop the desktop or change Bluetooth."""
from pathlib import Path
import argparse, array, fcntl, json, os, shutil, subprocess, sys

def touchscreen_info(path):
    descriptor=os.open(path,os.O_RDONLY|os.O_NONBLOCK)
    try:
        axes={}
        for name,code in (("slot",0x2f),("x",0x35),("y",0x36)):
            values=array.array("i",[0]*6)
            request=(2<<30)|(24<<16)|(ord("E")<<8)|(0x40+code)
            fcntl.ioctl(descriptor,request,values,True)
            axes[name]={"minimum":values[1],"maximum":values[2]}
        return {"path":str(path),"axes":axes}
    finally:os.close(descriptor)

def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--project",required=True)
    parser.add_argument("--lab",choices=("lab2","lab3","lab4","lab5_bt","test"),required=True)
    parser.add_argument("--touch");parser.add_argument("--serial",default="/dev/rfcomm0")
    parser.add_argument("--headless",action="store_true")
    args=parser.parse_args();project=Path(args.project).resolve(strict=True)
    failures=[];info={"project":str(project),"lab":args.lab,"checksAreReadOnly":True}
    binary=project/"out"/args.lab
    if not binary.is_file() or not os.access(binary,os.X_OK):failures.append(f"Build executable first: {binary}")
    if not args.headless:
        try:
            descriptor=os.open("/dev/fb0",os.O_RDONLY)
            try:
                values=array.array("I",[0]*40);fcntl.ioctl(descriptor,0x4600,values,True)
            finally:os.close(descriptor)
            info["framebuffer"]={"width":values[0],"height":values[1],"bitsPerPixel":values[6],
                "red":[values[8],values[9]],"green":[values[11],values[12]],"blue":[values[14],values[15]]}
            if (values[0],values[1],values[6],values[8],values[9],values[11],values[12],values[14],values[15])!=(1024,600,32,16,8,8,8,0,8):
                failures.append("Framebuffer format differs from course constants; adjust mode/code before running.")
        except OSError as error:failures.append(f"Framebuffer unavailable: {error}")
        if not os.access("/dev/fb0",os.R_OK|os.W_OK):failures.append("Framebuffer is not readable/writable.")
        for name in ("font.ttc", "test.jpg", "test.png"):
            if args.lab in ("lab3","test") or name=="font.ttc":
                if not (project/"out"/name).is_file():failures.append(f"Missing asset: out/{name}")
        if args.lab in ("lab4","lab5_bt"):
            devices=[]
            for path in ([Path(args.touch)] if args.touch else sorted(Path("/dev/input").glob("event*"))):
                try:devices.append(touchscreen_info(path))
                except OSError:continue
            info["protocolBTouchscreens"]=devices
            if not devices:failures.append("No protocol-B touchscreen detected; check its USB touch cable.")
            if len(devices)>1 and not args.touch:failures.append("Multiple touchscreens; choose --touch /dev/input/eventN explicitly.")
        if shutil.which("systemctl"):
            check=subprocess.run(["systemctl","is-active","display-manager"],capture_output=True,text=True)
            info["displayManager"]=check.stdout.strip()
            if check.returncode==0:
                failures.append("Board desktop is active. Follow PPT 37-38 to stop the board desktop before framebuffer experiments.")
    if args.lab=="lab5_bt":
        info["bluetoothTools"]={name:shutil.which(name) for name in ("bluetoothctl","rfcomm","sdptool","hciconfig")}
        if not Path(args.serial).exists():failures.append(f"Pair/connect the Bluetooth client and keep rfcomm watch running: {args.serial} absent.")
    info["problems"]=failures;print(json.dumps(info,ensure_ascii=False,indent=2))
    return bool(failures)
if __name__=="__main__":sys.exit(main())

#include "common.h"
#include <sys/ioctl.h>
#include <linux/fb.h>
#include <linux/kd.h>
#include <linux/vt.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <stdio.h>
#include <sys/mman.h>
#include <string.h>
#include <math.h>

#define RED	FB_COLOR(255,0,0)
#define ORANGE	FB_COLOR(255,165,0)
#define YELLOW	FB_COLOR(255,255,0)
#define GREEN	FB_COLOR(0,255,0)
#define CYAN	FB_COLOR(0,127,255)
#define BLUE	FB_COLOR(0,0,255)
#define PURPLE	FB_COLOR(139,0,255)
#define WHITE   FB_COLOR(255,255,255)
#define BLACK   FB_COLOR(0,0,0)

static int LCD_FB_FD;
static int *LCD_FB_BUF = NULL;
static int DRAW_BUF[SCREEN_WIDTH*SCREEN_HEIGHT];

static struct area {
	int x1, x2, y1, y2;
} update_area = {0,0,0,0};

#define AREA_SET_EMPTY(pa) do {\
	(pa)->x1 = SCREEN_WIDTH;\
	(pa)->x2 = 0;\
	(pa)->y1 = SCREEN_HEIGHT;\
	(pa)->y2 = 0;\
} while(0)

void fb_init(char *dev)
{
	int fd;
	struct fb_fix_screeninfo fb_fix;
	struct fb_var_screeninfo fb_var;

	if(LCD_FB_BUF != NULL) return; /*already done*/

	//进入终端图形模式
	fd = open("/dev/tty0",O_RDWR,0);
	ioctl(fd, KDSETMODE, KD_GRAPHICS);
	close(fd);

	//First: Open the device
	if((fd = open(dev, O_RDWR)) < 0){
		printf("Unable to open framebuffer %s, errno = %d\n", dev, errno);
		return;
	}
	if(ioctl(fd, FBIOGET_FSCREENINFO, &fb_fix) < 0){
		printf("Unable to FBIOGET_FSCREENINFO %s\n", dev);
		return;
	}
	if(ioctl(fd, FBIOGET_VSCREENINFO, &fb_var) < 0){
		printf("Unable to FBIOGET_VSCREENINFO %s\n", dev);
		return;
	}

	printf("framebuffer info: bits_per_pixel=%u,size=(%d,%d),virtual_pos_size=(%d,%d)(%d,%d),line_length=%u,smem_len=%u\n",
		fb_var.bits_per_pixel, fb_var.xres, fb_var.yres, fb_var.xoffset, fb_var.yoffset,
		fb_var.xres_virtual, fb_var.yres_virtual, fb_fix.line_length, fb_fix.smem_len);

	//Second: mmap
	void *addr = mmap(NULL, fb_fix.smem_len, PROT_READ|PROT_WRITE, MAP_SHARED, fd, 0);
	if(addr == (void *)-1){
		printf("failed to mmap memory for framebuffer.\n");
		return;
	}

	if((fb_var.xoffset != 0) ||(fb_var.yoffset != 0))
	{
		fb_var.xoffset = 0;
		fb_var.yoffset = 0;
		if(ioctl(fd, FBIOPAN_DISPLAY, &fb_var) < 0) {
			printf("FBIOPAN_DISPLAY framebuffer failed\n");
		}
	}

	LCD_FB_FD = fd;
	LCD_FB_BUF = addr;

	//set empty
	AREA_SET_EMPTY(&update_area);
	return;
}

static void _copy_area(int *dst, int *src, struct area *pa)
{
	int x, y, w, h;
	x = pa->x1; w = pa->x2-x;
	y = pa->y1; h = pa->y2-y;
	src += y*SCREEN_WIDTH + x;
	dst += y*SCREEN_WIDTH + x;
	while(h-- > 0){
		memcpy(dst, src, w*4);
		src += SCREEN_WIDTH;
		dst += SCREEN_WIDTH;
	}
}

static int _check_area(struct area *pa)
{
	if(pa->x2 == 0) return 0; //is empty

	if(pa->x1 < 0) pa->x1 = 0;
	if(pa->x2 > SCREEN_WIDTH) pa->x2 = SCREEN_WIDTH;
	if(pa->y1 < 0) pa->y1 = 0;
	if(pa->y2 > SCREEN_HEIGHT) pa->y2 = SCREEN_HEIGHT;

	if((pa->x2 > pa->x1) && (pa->y2 > pa->y1))
		return 1; //no empty

	//set empty
	AREA_SET_EMPTY(pa);
	return 0;
}

void fb_update(void)
{
	if(_check_area(&update_area) == 0) return; //is empty
	_copy_area(LCD_FB_BUF, DRAW_BUF, &update_area);
	AREA_SET_EMPTY(&update_area); //set empty
	return;
}

/*======================================================================*/

static void * _begin_draw(int x, int y, int w, int h)
{
	int x2 = x+w;
	int y2 = y+h;
	if(update_area.x1 > x) update_area.x1 = x;
	if(update_area.y1 > y) update_area.y1 = y;
	if(update_area.x2 < x2) update_area.x2 = x2;
	if(update_area.y2 < y2) update_area.y2 = y2;
	return DRAW_BUF;
}

void fb_draw_pixel(int x, int y, int color)
{
	if(x<0 || y<0 || x>=SCREEN_WIDTH || y>=SCREEN_HEIGHT) return;
	int *buf = _begin_draw(x,y,1,1);
/*---------------------------------------------------*/
	*(buf + y*SCREEN_WIDTH + x) = color;
/*---------------------------------------------------*/
	return;
}

void fb_draw_rect(int x, int y, int w, int h, int color)
{
	if(x < 0) { w += x; x = 0;}
	if(x+w > SCREEN_WIDTH) { w = SCREEN_WIDTH-x;}
	if(y < 0) { h += y; y = 0;}
	if(y+h >SCREEN_HEIGHT) { h = SCREEN_HEIGHT-y;}
	if(w<=0 || h<=0) return;
	int *buf = _begin_draw(x,y,w,h);
/*---------------------------------------------------*/
	int x0, y0;
	for(y0=y;y0<y+h;y0++){
	  for(x0=x;x0<x+w;x0++){
	    *(buf + y0*SCREEN_WIDTH + x0) = color;
	  }
	}
/*---------------------------------------------------*/
	return;
}

void fb_draw_line(int x1, int y1, int x2, int y2, int color)
{
/*---------------------------------------------------*/
	int xx, yy;
	int stepx = (x2>x1)?1:-1;
	int stepy = (y2>y1)?1:-1;
	int* buf = _begin_draw(0,0,SCREEN_WIDTH,SCREEN_HEIGHT);
	int slope = (x1==x2)?-1:abs((y2-y1)/(x2-x1));
	if(slope<1 && slope>=0)
	for(xx=x1;xx!=(x2+stepx);xx+=stepx){
        yy = (y2-y1)*(xx-x1)/(x2-x1) + y1;
		*(buf + yy*SCREEN_WIDTH + xx) = color;
	}
	else
	for(yy=y1;yy!=(y2+stepy);yy+=stepy){
        xx = (x2-x1)*(yy-y1)/(y2-y1) + x1;
		*(buf + yy*SCREEN_WIDTH + xx) = color;
	}

/*---------------------------------------------------*/
	return;
}

void fb_draw_image(int x, int y, fb_image *image, int color)
{
	if(image == NULL) return;

	int ix = 0; //image x  实际绘图的图像起始坐标  而x.y代表屏幕上的显示范围
	int iy = 0; //image y
	int w = image->pixel_w; //draw width
	int h = image->pixel_h; //draw height

	if(x<0) {w+=x; ix-=x; x=0;}
	if(y<0) {h+=y; iy-=y; y=0;}

	if(x+w > SCREEN_WIDTH) {
		w = SCREEN_WIDTH - x;
	}
	if(y+h > SCREEN_HEIGHT) {
		h = SCREEN_HEIGHT - y;
	}
	if((w <= 0)||(h <= 0)) return;

	int *buf = _begin_draw(x,y,w,h);
/*---------------------------------------------------------------*/
	//char *dst = (char *)(buf + y*SCREEN_WIDTH + x);
	//char *src; //不同的图像颜色格式定位不同
/*---------------------------------------------------------------*/

	if(image->color_type == FB_COLOR_RGB_8880) /*lab3: jpg*/
	{
		int y0, y3;
		char* dst = (char*)(buf+y*SCREEN_WIDTH+x);
		char *src = image->content;
		for(y0=y, y3=iy;y0<y+h;y0++,y3++){
			/*for(x0=x, x3=ix;x0<x+w;x0++,x3++){
				temp = (int*)(image->content+y3*image->pixel_w*4+x3*4);
				*(buf+y0*SCREEN_WIDTH+x0) = *temp;
			}*/
			memcpy(dst,src,w*4);
			dst += SCREEN_WIDTH*4;
			src += w*4;
		}

		return;
	}
	else if(image->color_type == FB_COLOR_RGBA_8888) /*lab3: png*/
	{
		//printf("you need implement fb_draw_image() FB_COLOR_RGBA_8888\n"); //exit(0);
		int x0, y0, x3, y3;
		unsigned char alpha;
		char* colord, *temp;
		for(y0=y, y3=iy;y0<y+h;y0++,y3++){
			for(x0=x, x3=ix;x0<x+w;x0++,x3++){
				colord = (char*)(buf+y0*SCREEN_WIDTH+x0);
				temp = image->content+y3*image->pixel_w*4+x3*4;
				alpha = (unsigned char)(temp[3]);
				switch (alpha){
					case 0: break;
					case 255:
					    colord[0] = temp[0];
						colord[1] = temp[1];
						colord[2] = temp[2];
						break;
					default:
						colord[0] += (((temp[0] - colord[0]) * alpha) >> 8);
						colord[1] += (((temp[1] - colord[1]) * alpha) >> 8);
						colord[2] += (((temp[2] - colord[2]) * alpha) >> 8);
				}
			}
		}
		return;
	}
	else if(image->color_type == FB_COLOR_ALPHA_8) /*lab3: font*/
	{
		//printf("you need implement fb_draw_image() FB_COLOR_ALPHA_8\n");
		int x0, y0, x3, y3;
		unsigned char alpha;
		char* colord, *temp;
		for(y0=y, y3=iy;y0<y+h;y0++,y3++){
			for(x0=x, x3=ix;x0<x+w;x0++,x3++){
				colord = (char*)(buf+y0*SCREEN_WIDTH+x0);
				temp = image->content+y3*image->pixel_w+x3;
				alpha = *temp;
				switch (alpha){
					case 0: break;
					case 255:
					    colord[0] = (color & 0xff);
						colord[1] = (color & 0xff00)>>8;
						colord[2] = (color & 0xff0000)>>16;
						break;
					default:
						colord[0] += ((((color & 0xff) - colord[0]) * alpha) >> 8);
						colord[1] += (((((color & 0xff00)>>8)- colord[1]) * alpha) >> 8);
						colord[2] += (((((color & 0xff0000)>>16) - colord[2]) * alpha) >> 8);
				}
			}
		}
		return;
	}
/*---------------------------------------------------------------*/
	return;
}

void fb_draw_border(int x, int y, int w, int h, int color)
{
	if(w<=0 || h<=0) return;
	fb_draw_rect(x, y, w, 1, color);
	if(h > 1) {
		fb_draw_rect(x, y+h-1, w, 1, color);
		fb_draw_rect(x, y+1, 1, h-2, color);
		if(w > 1) fb_draw_rect(x+w-1, y+1, 1, h-2, color);
	}
}

/** draw a text string **/
void fb_draw_text(int x, int y, char *text, int font_size, int color)
{
	fb_image *img;
	fb_font_info info;
	int i=0;
	int len = strlen(text);
	while(i < len)
	{
		img = fb_read_font_image(text+i, font_size, &info);
		if(img == NULL) break;
		fb_draw_image(x+info.left, y-info.top, img, color);
		fb_free_image(img);

		x += info.advance_x;
		i += info.bytes;
	}
	return;
}

