void fb_draw_circle(int x, int y, int r, int color)
{
	int w, h, x0, y0, left, right, top, bottom;
	if(x-r < 0) left = 0; else left = x-r;
	if(x+r > SCREEN_WIDTH) right = SCREEN_WIDTH; else right = x+r;
	if(y-r < 0) top = 0; else top = y-r;
	if(y+r >SCREEN_HEIGHT) bottom = SCREEN_HEIGHT; else bottom = y+r;
	w = right-left;
	h = bottom-top;
	x0 = left;
	y0 = top;

	int *buf = _begin_draw(x0,y0,w,h);
	for(y0=top;y0<=bottom;y0++){
		for(x0=left;x0<=right;x0++){
			double distance = sqrt((x0-x)*(x0-x)+(y0-y)*(y0-y));
			if(distance <= r){
				*(buf+y0*SCREEN_WIDTH+x0) = color;
			}
		}
	}
	return;
}


void imagecentralize(imageplus* imgplus, fb_image* img){
	imgplus->image = img;
	imgplus->w = img->pixel_w;
	imgplus->h = img->pixel_h;
	imgplus->x = 512 - imgplus->image->pixel_w/2;
	imgplus->y = 300 - imgplus->image->pixel_h/2;
	fb_draw_image(imgplus->x, imgplus->y, imgplus->image, BLACK);
	return;
}


void drawimage(imageplus* imgplus){
	if(imgplus->image == NULL) return;

	double ratio_incre = (double)(imgplus->image->pixel_w)/(imgplus->w);

	int ix = 0; //image x  实际绘图的图像起始坐标  而x.y代表屏幕上的显示范围
	int iy = 0; //image y
	int w = imgplus->w; //draw width
	int h = imgplus->h; //draw height
	int x = imgplus->x;
	int y = imgplus->y;

	if(x<0) {w+=x; ix-=x; x=0;}
	if(y<0) {h+=y; iy-=y; y=0;}

	if(x+w > SCREEN_WIDTH) {
		w = SCREEN_WIDTH - x;
	}
	if(y+h > SCREEN_HEIGHT) {
		h = SCREEN_HEIGHT - y;
	}
	if((w <= 0)||(h <= 0)) return;

	int *buf = _begin_draw(x,y,w,h);
	int *temp;

	//if(imgplus->image->color_type == FB_COLOR_RGB_8880) 
	//{
		double x3, y3;
		int x0, y0;
		for(y0=y, y3=iy;y0<y+h;y0++){
			for(x0=x, x3=ix;x0<x+w;x0++){
				temp = (int*)(imgplus->image->content+((int)y3)*imgplus->image->pixel_w*4+((int)x3)*4);
				*(buf+y0*SCREEN_WIDTH+x0) = *temp;
				x3 += ratio_incre;
			}
			y3 += ratio_incre;
		}
	//}
	return;
}


void imagescaling(imageplus* imgplus, int type){
	int zoom_size_x = 50;
	int zoom_size_y;
	int offset_size = 60;
	switch(type){
		case 0://fangda
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			zoom_size_y = (int)(zoom_size_x * ((double)(imgplus->image->pixel_h)/(imgplus->image->pixel_w)));
			imgplus->x -= zoom_size_x;
			imgplus->y -= zoom_size_y;
			imgplus->w += 2*zoom_size_x;
			imgplus->h += 2*zoom_size_y;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 1://suoxiao
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			zoom_size_y = (int)(zoom_size_x * ((double)(imgplus->image->pixel_h)/(imgplus->image->pixel_w)));
			imgplus->x += zoom_size_x;
			imgplus->y += zoom_size_y;
			imgplus->w -= 2*zoom_size_x;
			imgplus->h -= 2*zoom_size_y;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 2://zuoyi
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imgplus->x -= offset_size;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 3://youyi
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imgplus->x += offset_size;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 4://shangyi
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imgplus->y -= offset_size;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 5://xiayi
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imgplus->y += offset_size;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 6://quanping
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imgplus->w = SCREEN_WIDTH;
			imgplus->h = (int)(SCREEN_WIDTH * ((double)(imgplus->image->pixel_h)/(imgplus->image->pixel_w)));
			imgplus->x = 0;
			imgplus->y = 0;
			drawimage(imgplus);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		case 7://huifu
			fb_draw_rect(0,0,SCREEN_WIDTH,SCREEN_HEIGHT,BLACK);
			imagecentralize(imgplus, imgplus->image);
			fb_draw_rect(0,0,100,100,PURPLE);
			break;
		default:
			break;
	}
	return;

