static int touch_fd;
static int radius[5] = {45,47,49,51,53};
static struct old_pos{
	int x;
	int y;
} old[5];

static void touch_event_cb(int fd)
{
	int type,x,y,finger, color;
	type = touch_read(fd, &x,&y,&finger);
	switch(type){
	case TOUCH_PRESS:
		printf("TOUCH_PRESS:x=%d,y=%d,finger=%d\n",x,y,finger);
		switch(finger){
			case 0: color = ORANGE;break;
			case 1: color = BLUE;break;
			case 2: color = RED;break;
			case 3: color = GREEN;break;
			case 4: color = BLACK;break;
			default: break;
		}
		fb_draw_circle(x, y, radius[finger], color);
		old[finger].x = x;
		old[finger].y = y;
		break;
	case TOUCH_MOVE:
		switch(finger){
			case 0: color = ORANGE;break;
			case 1: color = BLUE;break;
			case 2: color = RED;break;
			case 3: color = GREEN;break;
			case 4: color = BLACK;break;
			default: break;
		}
		fb_draw_circle(old[finger].x, old[finger].y, radius[finger]+2, COLOR_BACKGROUND);
		fb_draw_circle(x, y, radius[finger], color);
		old[finger].x = x;
		old[finger].y = y;
		break;
	case TOUCH_RELEASE:
		printf("TOUCH_RELEASE:x=%d,y=%d,finger=%d\n",x,y,finger);
		fb_draw_circle(x, y, radius[finger]+2, COLOR_BACKGROUND);
		break;
	case TOUCH_ERROR:
		printf("close touch fd\n");
		close(fd);
		task_delete_file(fd);
		break;
	default:
		return;
	}
	fb_update();
	return;
}

