static void expect_touch(int type,int x,int y,int finger)
{
    CHECK(touch_state_pop(&state,&sample));
    CHECK(sample.type==type && sample.x==x && sample.y==y && sample.finger==finger);
}
static void touch_tests(void)
{
    touch_state_init(&state);
    for(int i=0;i<5;++i) {
        touch_state_slot(&state,i);touch_state_tracking(&state,100+i);
        touch_state_position(&state,0,10+i);touch_state_position(&state,1,20+i);
    }
    CHECK(!touch_state_pop(&state,&sample)); /* Until SYN_REPORT no incomplete coordinate pair escapes. */
    touch_state_sync(&state);
    for(int i=0;i<5;++i) expect_touch(TOUCH_PRESS,10+i,20+i,i);
    CHECK(!touch_state_pop(&state,&sample));
    touch_state_slot(&state,0);touch_state_position(&state,0,42);touch_state_sync(&state);
    expect_touch(TOUCH_MOVE,42,20,0);CHECK(!touch_state_pop(&state,&sample));
    touch_state_sync(&state);CHECK(!touch_state_pop(&state,&sample));
    touch_state_slot(&state,99);touch_state_position(&state,0,999);touch_state_tracking(&state,-1);
    touch_state_sync(&state);CHECK(!touch_state_pop(&state,&sample));
    touch_state_slot(&state,0);touch_state_tracking(&state,200);
    touch_state_position(&state,0,50);touch_state_position(&state,1,60);touch_state_sync(&state);
    expect_touch(TOUCH_RELEASE,42,20,0);expect_touch(TOUCH_PRESS,50,60,0);
    for(int i=0;i<5;++i) {touch_state_slot(&state,i);touch_state_tracking(&state,-1);}
    touch_state_sync(&state);expect_touch(TOUCH_RELEASE,50,60,0);
    for(int i=1;i<5;++i) expect_touch(TOUCH_RELEASE,10+i,20+i,i);
    CHECK(!touch_state_pop(&state,&sample));
    CHECK(touch_scale_axis(0,0,4095,1024)==0);
    CHECK(touch_scale_axis(4095,0,4095,1024)==1023);
    CHECK(touch_scale_axis(-100,0,4095,600)==0);
    CHECK(touch_scale_axis(5000,0,4095,600)==599);
    CHECK(touch_scale_axis(512,0,1023,1024)==512);
    CHECK(touch_scale_axis(0,-100,100,601)==300);
    CHECK(touch_scale_axis(INT_MAX,INT_MIN,INT_MAX,1024)==1023);
    printf("PASS: protocol-B replay (five slots, SYN frames, partial axes, replacement, release, scaling)\n");
}
static void text_tests(void)
{
    const char *text="你好，Orange Pi!\nsecond\r\n";
    for(size_t split=0;split<=strlen(text);++split) {
        bt_text_stream s;message_count=0;bt_text_init(&s,capture,NULL);
        bt_text_feed(&s,(const uint8_t *)text,split);
        bt_text_feed(&s,(const uint8_t *)text+split,strlen(text)-split);
        CHECK(message_count==2);CHECK(strcmp(messages[0],"你好，Orange Pi!")==0);
        CHECK(strcmp(messages[1],"second")==0);
    }
    bt_text_stream s;message_count=0;bt_text_init(&s,capture,NULL);
    const uint8_t first[]={0xe4};bt_text_feed(&s,first,1);bt_text_flush(&s,0);
    CHECK(message_count==0);
    const uint8_t rest[]={0xbd,0xa0,'\n'};bt_text_feed(&s,rest,sizeof(rest));
    CHECK(message_count==1 && strcmp(messages[0],"你")==0);
    message_count=0;bt_text_init(&s,capture,NULL);
    bt_text_feed(&s,(const uint8_t *)"no newline",10);bt_text_flush(&s,0);
    CHECK(message_count==1 && strcmp(messages[0],"no newline")==0);
    message_count=0;bt_text_init(&s,capture,NULL);
    for(int i=0;i<200;++i) bt_text_feed(&s,(const uint8_t *)"嵌",3);
    bt_text_flush(&s,1);size_t bytes=0;
    for(unsigned i=0;i<message_count;++i) {CHECK(strlen(messages[i])%3==0);bytes+=strlen(messages[i]);}
    CHECK(bytes==600);
    message_count=0;bt_text_init(&s,capture,NULL);
    const uint8_t invalid[]={0xed,0xa0,0x80,0,27,'\n'};
    bt_text_feed(&s,invalid,sizeof(invalid));CHECK(message_count==1);
    CHECK(strcmp(messages[0],"?????")==0);
    message_count=0;bt_text_init(&s,capture,NULL);
    bt_text_feed(&s,first,1);bt_text_flush(&s,1);CHECK(message_count==1 && strcmp(messages[0],"?")==0);
    printf("PASS: Bluetooth text stream (every split point, UTF-8, CRLF, idle flush, long/invalid input)\n");
}
static int write_step;
static char transmitted[256];
static size_t transmitted_length;
static int fake_writer(const char *bytes,size_t length,void *context)
{
    (void)context;
    int result=write_step==0 ? 2 : write_step==1 ? BT_IO_RETRY : write_step==2 ? BT_IO_WAIT : (int)length;
    ++write_step;
    if(result>0) {memcpy(transmitted+transmitted_length,bytes,(size_t)result);transmitted_length+=(size_t)result;}
    return result;
}
static void queue_tests(void)
{
    bt_tx_queue q={0};
    CHECK(bt_tx_enqueue(&q,"hello\n",6)==0);
    CHECK(bt_tx_flush(&q,fake_writer,NULL)==0);
    CHECK(q.offset==2 && q.length==6);
    CHECK(bt_tx_enqueue(&q,"next\n",5)==0);
    CHECK(bt_tx_flush(&q,fake_writer,NULL)==1);
    CHECK(q.offset==0 && q.length==0);
    CHECK(transmitted_length==11 && memcmp(transmitted,"hello\nnext\n",11)==0);
    char full[256];memset(full,'x',sizeof(full));
    CHECK(bt_tx_enqueue(&q,full,sizeof(full))==0);
    CHECK(bt_tx_enqueue(&q,"x",1)<0 && q.length==sizeof(full));
    printf("PASS: transmit queue (partial write, EINTR retry, EAGAIN resume, order, capacity)\n");
}
